// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type DecliningGraphProps = Record<string, any>;

const DecliningGraph: React.FC<DecliningGraphProps> = ({
  backgroundColor = "#0d1117",
  transparentBackground = false,
  durationInSeconds = 10,
  title = "Final Student Enrollment",
  subtitle = "The institution has officially ceased operations",
  lineColor = "#ffffff",
  textColor = "#f0f6fc",
  gridColor = "#30363d",
  data = [
    { label: "1990", value: 8500 },
    { label: "1995", value: 11200 },
    { label: "2000", value: 13400 },
    { label: "2005", value: 10800 },
    { label: "2010", value: 7500 },
    { label: "2015", value: 3900 },
    { label: "2020", value: 1000 },
    { label: "2024", value: 0 },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency check
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive layout measurements
  const PADDING_X = width * 0.12;
  const PADDING_Y = height * 0.15;
  const graphWidth = width - PADDING_X * 2;
  const graphHeight = height - PADDING_Y * 2 - 150; // Leave space for title

  // Mathematical bounds for the graph
  const actualMax = Math.max(...data.map((d) => d.value));
  const maxVal = actualMax > 0 ? actualMax * 1.1 : 1; // 10% headroom above max value

  // Generate points
  const points = data.map((d, i) => {
    const x = (i / (data.length - 1)) * graphWidth;
    const y = graphHeight - (d.value / maxVal) * graphHeight;
    return { x, y, ...d };
  });

  // Construct SVG paths
  const pathD = points
    .map((p, i) => (i === 0 ? `M ${p.x} ${p.y}` : `L ${p.x} ${p.y}`))
    .join(" ");

  const areaD =
    points.length > 0
      ? `${pathD} L ${points[points.length - 1].x} ${graphHeight} L ${points[0].x} ${graphHeight} Z`
      : "";

  // Animation Timings
  const titleProgress = spring({
    frame,
    fps,
    config: { damping: 200 },
    delay: 5,
  });

  const titleOpacity = interpolate(titleProgress, [0, 1], [0, 1]);
  const titleY = interpolate(titleProgress, [0, 1], [30, 0]);

  // Reveal graph line steadily over time
  const graphRevealDuration = Math.min(fps * 4, (durationInSeconds * fps) / 2); // Takes 4s max
  const graphRevealProgress = interpolate(
    frame,
    [30, 30 + graphRevealDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      {/* Title Section */}
      <div
        style={{
          position: "absolute",
          top: PADDING_Y,
          left: PADDING_X,
          opacity: titleOpacity,
          transform: `translateY(${titleY}px)`,
          display: "flex",
          flexDirection: "column",
          gap: "12px",
        }}
      >
        <h1
          style={{
            margin: 0,
            fontSize: "64px",
            fontWeight: 800,
            color: textColor,
            letterSpacing: "-0.02em",
          }}
        >
          {title}
        </h1>
        <p
          style={{
            margin: 0,
            fontSize: "32px",
            fontWeight: 400,
            color: textColor,
            opacity: 0.7,
          }}
        >
          {subtitle}
        </p>
      </div>

      {/* Main Graph Container */}
      <div
        style={{
          position: "absolute",
          top: PADDING_Y + 180,
          left: PADDING_X,
          width: graphWidth,
          height: graphHeight,
        }}
      >
        {/* Y-Axis Grid Lines */}
        {[0, 0.25, 0.5, 0.75, 1].map((pct, i) => {
          const y = graphHeight - pct * graphHeight;
          const labelValue = Math.round(maxVal * pct);
          const gridOpacity = interpolate(frame, [15 + i * 5, 30 + i * 5], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          return (
            <React.Fragment key={`grid-${i}`}>
              <div
                style={{
                  position: "absolute",
                  left: 0,
                  top: y,
                  width: "100%",
                  height: "2px",
                  backgroundColor: gridColor,
                  opacity: gridOpacity * 0.5,
                  transform: `scaleX(${gridOpacity})`,
                  transformOrigin: "left center",
                }}
              />
              <div
                style={{
                  position: "absolute",
                  left: -80,
                  top: y - 14,
                  width: "60px",
                  textAlign: "right",
                  color: textColor,
                  opacity: gridOpacity * 0.6,
                  fontSize: "20px",
                  fontWeight: 500,
                }}
              >
                {labelValue >= 1000 ? `${(labelValue / 1000).toFixed(1)}k` : labelValue}
              </div>
            </React.Fragment>
          );
        })}

        {/* SVG Drawing Layer */}
        <svg
          width="100%"
          height="100%"
          style={{
            overflow: "visible",
            position: "absolute",
            top: 0,
            left: 0,
          }}
        >
          <defs>
            <linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor={lineColor} stopOpacity={0.6} />
              <stop offset="100%" stopColor={lineColor} stopOpacity={0.0} />
            </linearGradient>
            <clipPath id="graphRevealClip">
              <rect
                x={-20} // buffer for thick strokes
                y={-50} // buffer for top dots
                width={graphWidth * graphRevealProgress + 40}
                height={graphHeight + 100}
              />
            </clipPath>
          </defs>

          <g clipPath="url(#graphRevealClip)">
            {/* Area Fill */}
            <path
              d={areaD}
              fill="url(#areaGradient)"
              style={{ transition: "none" }}
            />
            {/* Line Draw */}
            <path
              d={pathD}
              fill="none"
              stroke={lineColor}
              strokeWidth={8}
              strokeLinejoin="round"
              strokeLinecap="round"
              style={{ transition: "none" }}
            />
          </g>
        </svg>

        {/* Interactive Dots and Labels (overlay) */}
        {points.map((point, i) => {
          // Calculate when this specific dot should appear based on the reveal progress
          const revealTargetPct = i / (data.length - 1);
          // Map the graph's overall time range to this specific point's appearance time
          const pointRevealFrame = 30 + revealTargetPct * graphRevealDuration;
          
          const dotScale = spring({
            frame,
            fps,
            delay: pointRevealFrame,
            config: { damping: 14, mass: 0.8 },
          });

          // Animate the number counting up rapidly as it appears
          const animatedValue = Math.floor(
            interpolate(dotScale, [0, 1], [0, point.value])
          );

          return (
            <div
              key={`point-${i}`}
              style={{
                position: "absolute",
                left: point.x,
                top: 0,
                bottom: 0,
                width: "2px",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
              }}
            >
              {/* Data Dot */}
              <div
                style={{
                  position: "absolute",
                  top: point.y,
                  transform: `translate(-50%, -50%) scale(${dotScale})`,
                  width: "24px",
                  height: "24px",
                  backgroundColor: bgColor,
                  border: `6px solid ${lineColor}`,
                  borderRadius: "50%",
                  zIndex: 10,
                }}
              />

              {/* Data Value Hover Label */}
              <div
                style={{
                  position: "absolute",
                  top: point.y - 60,
                  transform: `translate(-50%, ${interpolate(dotScale, [0, 1], [20, 0])}px)`,
                  opacity: dotScale,
                  color: textColor,
                  fontSize: "28px",
                  fontWeight: 700,
                  textShadow: `0 4px 12px ${backgroundColor}`,
                  whiteSpace: "nowrap",
                }}
              >
                {animatedValue.toLocaleString()}
              </div>

              {/* X-Axis Label */}
              <div
                style={{
                  position: "absolute",
                  bottom: -60,
                  transform: `translate(-50%, ${interpolate(dotScale, [0, 1], [-20, 0])}px)`,
                  color: textColor,
                  opacity: dotScale * 0.7,
                  fontSize: "24px",
                  fontWeight: 500,
                }}
              >
                {point.label}
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default DecliningGraph;